  p_QualityRank_07772d8728d8 INTEGER;
  p_ExecutionCostRank_07772d8728d8 INTEGER;
  p_UsesTemplate_07772d8728d8 BOOLEAN;
  p_AuditQueryRuns_07772d8728d8 BOOLEAN;
  p_CacheEnabled_07772d8728d8 BOOLEAN;
