  p_CacheMaxSize_07772d8728d8 INTEGER;
  p_EmbeddingVector_07772d8728d8 TEXT;
  p_EmbeddingModelID_07772d8728d8 UUID;
  p_CacheValidationSQL_07772d8728d8 TEXT;
  p_SQLDialectID_07772d8728d8 UUID;
